const { ShopifyClientError } = require('../errors');

const BLOGS_QUERY = `
  query($cursor: String) {
    blogs(first: 250, after: $cursor) {
      edges {
        node {
          id
          title
          handle
          createdAt
          articles(first: 250) {
            edges {
              node {
                id
                title
                handle
                body
                publishedAt
                tags
              }
            }
          }
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
`;

const BLOG_CREATE_MUTATION = `
  mutation blogCreate($blog: BlogCreateInput!) {
    blogCreate(blog: $blog) {
      blog {
        id
        title
        handle
      }
      userErrors {
        field
        message
      }
    }
  }
`;

const BLOG_UPDATE_MUTATION = `
  mutation blogUpdate($id: ID!, $blog: BlogUpdateInput!) {
    blogUpdate(id: $id, blog: $blog) {
      blog {
        id
        title
        handle
      }
      userErrors {
        field
        message
      }
    }
  }
`;

const BLOG_DELETE_MUTATION = `
  mutation deleteBlog($id: ID!) {
    blogDelete(id: $id) {
      deletedBlogId
      userErrors {
        field
        message
      }
    }
  }
`;

function throwOnUserErrors(operation, userErrors) {
  if (!userErrors || userErrors.length === 0) {
    return;
  }

  throw new ShopifyClientError(`${operation} failed`, {
    code: 'SHOPIFY_USER_ERROR',
    details: {
      userErrors
    }
  });
}

function createBlogsClient({ graphql }) {
  return {
    async listAll() {
      const blogs = [];
      let hasNextPage = true;
      let cursor = null;

      while (hasNextPage) {
        const data = await graphql(BLOGS_QUERY, { cursor });
        blogs.push(...data.blogs.edges.map((edge) => edge.node));
        hasNextPage = data.blogs.pageInfo.hasNextPage;
        cursor = data.blogs.pageInfo.endCursor;
      }

      return blogs;
    },

    async create(blogData) {
      const data = await graphql(BLOG_CREATE_MUTATION, {
        blog: {
          title: blogData.title,
          handle: blogData.handle
        }
      });

      throwOnUserErrors('Blog create', data.blogCreate.userErrors);
      return data.blogCreate.blog;
    },

    async update(blogId, blogData) {
      const data = await graphql(BLOG_UPDATE_MUTATION, {
        id: blogId,
        blog: {
          title: blogData.title
        }
      });

      throwOnUserErrors('Blog update', data.blogUpdate.userErrors);
      return data.blogUpdate.blog;
    },

    async delete(blogId) {
      const data = await graphql(BLOG_DELETE_MUTATION, { id: blogId });
      throwOnUserErrors('Blog delete', data.blogDelete.userErrors);
      return data.blogDelete.deletedBlogId;
    }
  };
}

module.exports = {
  createBlogsClient,
  BLOGS_QUERY,
  BLOG_CREATE_MUTATION,
  BLOG_UPDATE_MUTATION,
  BLOG_DELETE_MUTATION
};
